import{_ as t,o as e,c as n,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"形式化方法卷 · 用数学证明\\"系统是对的\\"","description":"","frontmatter":{},"headers":[],"relativePath":"formal/index.md","filePath":"formal/README.md","lastUpdated":1788475713000}'),o={name:"formal/index.md"};function r(l,a,i,d,p,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="形式化方法卷-·-用数学证明-系统是对的" tabindex="-1">形式化方法卷 · 用数学证明&quot;系统是对的&quot; <a class="header-anchor" href="#形式化方法卷-·-用数学证明-系统是对的" aria-label="Permalink to &quot;形式化方法卷 · 用数学证明&quot;系统是对的&quot;&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>&quot;测试能证明有 bug，但永远不能证明没 bug。&quot;<strong>形式化方法（Formal Methods）<strong>用数学严格证明系统的性质：模型检查自动穷举状态空间，定理证明器像数学证明一样推理，程序验证用逻辑保证代码符合规格。它是</strong>可靠性要求最高领域</strong>（分布式共识、加密、编译器、航空/核工业、区块链）的黄金标准——TLA+ 验过 Raft、Coq 验过 CompCert 编译器、seL4 用 Isabelle/HOL 证明了 OS 内核。</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[你写了个分布式共识算法]</span></span>
<span class="line"><span>  └─&gt; 测试跑了 1000 次都过 → 但并发/网络故障组合无穷, 测不完</span></span>
<span class="line"><span>        └─&gt; 模型检查 (TLA+): 穷举&quot;小规模状态空间&quot;, 找反例</span></span>
<span class="line"><span>              └─&gt; 写规格 + 不变量, 自动验证: 活锁/死锁/不满足性质</span></span>
<span class="line"><span>                    └─&gt; 但要证明&quot;代码实现 = 规格&quot; → 需要更强的工具</span></span>
<span class="line"><span>                          └─&gt; 定理证明 (Coq/Lean): 证明器人机交互证明</span></span>
<span class="line"><span>                                └─&gt; Curry-Howard: 命题=类型, 证明=程序</span></span>
<span class="line"><span>                                      └─&gt; 程序验证: Hoare 逻辑/符号执行</span></span>
<span class="line"><span>                                            └─&gt; 编译器被证明 (CompCert)</span></span>
<span class="line"><span>                                              └─&gt; 内核被证明 (seL4)</span></span>
<span class="line"><span>                                                    └─&gt; 安全关键系统的护城河</span></span></code></pre></div><p>每一层工具解决&quot;可靠性&quot;的不同粒度：测试给信心、模型检查给反例、定理证明给正确性证明、程序验证把证明连到真实代码。</p><h2 id="你将带走什么" tabindex="-1">你将带走什么 <a class="header-anchor" href="#你将带走什么" aria-label="Permalink to &quot;你将带走什么&quot;">​</a></h2><p>读完应能：</p><ol><li>说清测试、模型检查、定理证明三者的区别与适用场景。</li><li>用 TLA+ 写一个简单系统（如互斥锁）的规格并跑 TLC 模型检查。</li><li>理解 Coq/Lean 的依赖类型与 Curry-Howard，知道定理证明器和&quot;智能代码编辑器&quot;的区别。</li><li>理解 Hoare 三元组和程序验证的核心思路，知道符号执行、形式语义是什么。</li><li>知道哪些工业系统真用形式化方法（TLA+/Coq/Isabelle/seL4），以及为什么只在关键处用。</li></ol><h2 id="章节结构" tabindex="-1">章节结构 <a class="header-anchor" href="#章节结构" aria-label="Permalink to &quot;章节结构&quot;">​</a></h2><ul><li><a href="./">开篇: 用数学证明&quot;系统是对的&quot;</a> ← 当前</li><li><a href="./model-checking-tla">1. 模型检查与 TLA+: 穷举状态空间找反例</a></li><li><a href="./coq-lean">2. 定理证明: Coq / Lean / 依赖类型 / Curry-Howard</a></li><li><a href="./program-verification">3. 程序验证: Hoare 逻辑 / 符号执行 / 形式语义</a></li></ul><h2 id="与其余部分的接口" tabindex="-1">与其余部分的接口 <a class="header-anchor" href="#与其余部分的接口" aria-label="Permalink to &quot;与其余部分的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>本卷章节</th><th>接口</th></tr></thead><tbody><tr><td>TLA+ / 模型检查</td><td>分布式 §共识（Paxos/Raft 用 TLA+ 验证）、并发 §一致性、DSA §图搜索</td></tr><tr><td>Coq / Lean</td><td>理论 §形式语言/自动机、编译 §类型系统/HM、数学 §逻辑</td></tr><tr><td>程序验证</td><td>编译 §SSA/语义分析、软件工程 §代码质量、数学 §Hoare 逻辑基础</td></tr></tbody></table><h2 id="这卷不是什么" tabindex="-1">这卷不是什么 <a class="header-anchor" href="#这卷不是什么" aria-label="Permalink to &quot;这卷不是什么&quot;">​</a></h2><ul><li><strong>不是</strong>一本 Coq/Lean 完整教程（那需要单独成书）。给的是&quot;心智模型 + 最小可跑示例&quot;。</li><li><strong>不是</strong>说测试没用。形式化方法解决的是<strong>测试覆盖不到的</strong>（并发组合、无穷输入、安全关键）。</li><li><strong>不是</strong>所有项目都该上。它成本高，只在<strong>正确性代价极高</strong>时用——这是关键判断。</li></ul><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用哪个</th></tr></thead><tbody><tr><td>分布式算法（共识/复制/时钟）</td><td>TLA+ 模型检查</td></tr><tr><td>加密协议 / 密码实现</td><td>定理证明 + 程序验证</td></tr><tr><td>编译器 / 内核 / 调度器</td><td>Coq / Isabelle 证明</td></tr><tr><td>区块链共识 / 智能合约</td><td>模型检查 + 符号执行</td></tr><tr><td>普通 CRUD 应用</td><td><strong>不用</strong>（测试足够）</td></tr></tbody></table><hr><p>下一篇: <a href="./model-checking-tla">1. 模型检查与 TLA+: 穷举状态空间找反例</a>.</p>`,19)])])}const q=t(o,[["render",r]]);export{u as __pageData,q as default};
